<?php
 namespace Pterodactyl\Http\Controllers\Admin; use Illuminate\View\View; use Illuminate\Http\Request; use Pterodactyl\Models\User; use Pterodactyl\Models\Model; use Pterodactyl\Services\Dezerx\Demo; use Pterodactyl\Services\Dezerx\Staff\Staff; use Pterodactyl\Services\Dezerx\Staff\StaffRequests; use Pterodactyl\Models\Dezerx\StaffProfile; use Pterodactyl\Models\Dezerx\StaffRequest; use Illuminate\Support\Collection; use Illuminate\Http\RedirectResponse; use Prologue\Alerts\AlertsMessageBag; use Spatie\QueryBuilder\QueryBuilder; use Illuminate\View\Factory as ViewFactory; use Pterodactyl\Exceptions\DisplayException; use Pterodactyl\Http\Controllers\Controller; use Illuminate\Contracts\Translation\Translator; use Pterodactyl\Services\Users\UserUpdateService; use Pterodactyl\Traits\Helpers\AvailableLanguages; use Pterodactyl\Services\Users\UserCreationService; use Pterodactyl\Services\Users\UserDeletionService; use Pterodactyl\Http\Requests\Admin\UserFormRequest; use Pterodactyl\Http\Requests\Admin\NewUserFormRequest; use Pterodactyl\Contracts\Repository\UserRepositoryInterface; class UserController extends Controller { use AvailableLanguages; public function __construct( protected AlertsMessageBag $alert, protected UserCreationService $creationService, protected UserDeletionService $deletionService, protected Translator $translator, protected UserUpdateService $updateService, protected UserRepositoryInterface $repository, protected ViewFactory $view, ) { } public function index(Request $request): View { $users = QueryBuilder::for( User::query()->select('users.*') ->selectRaw('COUNT(DISTINCT(subusers.id)) as subuser_of_count') ->selectRaw('COUNT(DISTINCT(servers.id)) as servers_count') ->leftJoin('subusers', 'subusers.user_id', '=', 'users.id') ->leftJoin('servers', 'servers.owner_id', '=', 'users.id') ->groupBy('users.id') ) ->allowedFilters(['username', 'email', 'uuid']) ->defaultSort('-root_admin') ->allowedSorts(['id', 'uuid']) ->paginate(50); return view('admin.users.index', ['users' => $users]); } public function create(): View { return view('admin.users.new', [ 'languages' => $this->getAvailableLanguages(true), ]); } public function view(User $user): View { return view('admin.users.view', [ 'user' => $user, 'languages' => $this->getAvailableLanguages(true), 'demoPassword' => $user->demo ? (Demo::credentials()['password'] ?? null) : null, ]); } public function delete(Request $request, User $user): RedirectResponse { if ($request->user()->is($user)) { throw new DisplayException(__('admin/user.exceptions.delete_self')); } $this->deletionService->handle($user); return redirect()->route('admin.users'); } public function store(NewUserFormRequest $request): RedirectResponse { $user = $this->creationService->handle($request->normalize()); $this->alert->success($this->translator->get('admin/user.notices.account_created'))->flash(); $this->syncDemo($request, $user); return redirect()->route('admin.users.view', $user->id); } public function update(UserFormRequest $request, User $user): RedirectResponse { $this->updateService ->setUserLevel(User::USER_LEVEL_ADMIN) ->handle($user, $request->normalize()); $this->alert->success(trans('admin/user.notices.account_updated'))->flash(); $this->syncDemo($request, $user->refresh()); $this->syncStaff($request, $user->refresh()); return redirect()->route('admin.users.view', $user->id); } private function syncStaff(Request $request, User $user): void { $wanted = $request->boolean('staff'); if ($wanted === ($user->staff === true)) { return; } if ($wanted) { if (Staff::accountSlotsLeft() < 1) { $this->alert->danger( 'This panel already has as many support staff accounts as it is set to allow. Raise the limit under Support Staff first.' )->flash(); return; } $user->forceFill(['staff' => true])->saveOrFail(); $profile = $user->staffProfile; if ($profile === null) { StaffProfile::query()->create(['user_id' => $user->id, 'available' => true]); } else { $profile->forceFill(['available' => true])->saveOrFail(); } $this->alert->info(e($user->username) . ' is now support staff, and will see the support queue.')->flash(); return; } $user->forceFill(['staff' => false])->saveOrFail(); $profile = $user->staffProfile; if ($profile !== null) { $profile->forceFill(['available' => false])->saveOrFail(); } $ended = 0; $requests = app(StaffRequests::class); foreach (StaffRequest::query()->open()->where('staff_id', $user->id)->cursor() as $session) { $requests->revoke($session, $request->user(), 'The account is no longer support staff.'); ++$ended; } $this->alert->info($ended === 0 ? e($user->username) . ' is no longer support staff.' : e($user->username) . ' is no longer support staff, and ' . $ended . ' open ' . ($ended === 1 ? 'session was' : 'sessions were') . ' ended.')->flash(); } private function syncDemo(Request $request, User $user): void { if ($request->boolean('demo')) { $wasAdmin = $user->root_admin; $password = Demo::promote($user, (string) $request->input('password', '')); if ($wasAdmin) { $this->alert->warning( 'Administrator rights were removed: a demo account whose password is printed on the sign-in screen cannot also be an administrator.' )->flash(); } $this->alert->info( 'This is now the demo account, and the only one. Its credentials are shown on the sign-in screen: ' . e($user->username) . ' / ' . e($password) )->flash(); return; } if ($user->demo) { Demo::demote($user); $this->alert->info( 'This is no longer the demo account. Its credentials have been taken off the sign-in screen, but its password is unchanged, so set a new one if it was ever public.' )->flash(); } } public function json(Request $request): Model|Collection { $users = QueryBuilder::for(User::query())->allowedFilters(['email'])->paginate(25); if ($request->query('user_id')) { $user = User::query()->findOrFail($request->input('user_id')); $user->md5 = md5(strtolower($user->email)); return $user; } return $users->map(function ($item) { $item->md5 = md5(strtolower($item->email)); return $item; }); } } 